function toast(msg){$('toast').textContent=msg;$('toast').classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.add('hidden'),3600)}
function errMsg(e){return(e&&e.message)||String(e)}
function showLoginConnectionError(message){const area=$('loginError');area.textContent=message;area.classList.remove('hidden');}
async function testBackendConnection(){const btn=$('testBackendBtn');btn.disabled=true;$('backendStatus').textContent='Testing connection…';try{const r=await CESApi.call('health');if(!String(r.version||'').startsWith('V34'))throw new Error('Apps Script is '+(r.version||'unknown')+'. Deploy V34 Code.gs + Setup.gs as a new version, then verify the /exec URL.');$('backendStatus').textContent='Connected • '+r.version;$('loginError').classList.add('hidden');}catch(e){const m=errMsg(e);$('backendStatus').textContent='Connection check failed';showLoginConnectionError(/RPC method not allowed/.test(m)?'Backend is reachable but not updated to V34. Redeploy Apps Script as a new version.':m);}finally{btn.disabled=false;}}
function clearSessionOnExpiry(reason){clearInterval(S.syncTimer);S.token=null;S.profile=null;sessionStorage.removeItem('ces_token');$('appView')?.classList.add('hidden');$('loginView')?.classList.remove('hidden');showLoginConnectionError(reason||'Session expired. Please sign in again.');setSyncState('Signed out','Session ended','red');}
function statusClass(s){const x=String(s||'').toLowerCase();return {'active':'st-active','decom':'st-decommission','non-renew':'st-nonrenew','renewal':'st-renewal','added':'st-added','in warranty':'st-warranty','defect':'st-defective','replace':'st-replace','unclassified':'st-other'}[x]||'st-other'}
function deltaClass(v){return v===null||v===undefined?'flat':Number(v)>0?'up':Number(v)<0?'down':'flat'}
function initialOf(name){const x=String(name||'U').trim();return x?x.charAt(0).toUpperCase():'U'}
function setSyncState(text,sub,state='orange'){ $('syncLabel').textContent=text;$('syncSub').textContent=sub||'';$('syncDot').className='sync-dot status-'+state;const dot=$('liveStatusPill').querySelector('.status-dot');dot.className='status-dot '+(state==='green'?'green':state==='red'?'red':'orange');$('liveStatusPill').querySelector('span:last-child').textContent=state==='green'?'LIVE':state==='red'?'SYNC ERROR':'CHECKING'; }
function fillSelect(id,values,placeholder){const el=$(id),keep=el.value;el.innerHTML=`<option value="">${esc(placeholder)}</option>`+(values||[]).map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');if((values||[]).includes(keep))el.value=keep;}
function fillYear(id,years,selected){$(id).innerHTML=(years||[]).map(y=>`<option value="${y}">${y}</option>`).join('');if(selected)$(id).value=String(selected)}
function daysUntil(v){const m=String(v||'').match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return null;const d=Date.UTC(+m[1],+m[2]-1,+m[3]);const f=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const o={};f.forEach(x=>o[x.type]=x.value);const today=Date.UTC(+o.year,+o.month-1,+o.day);return Math.round((d-today)/86400000)}
function statusBadge(s){return `<span class="status ${statusClass(s)}">${esc(s||'Other')}</span>`}
function actionButton(action,id,title,iconName){return `<button class="action-btn" data-action="${action}" data-id="${esc(id)}" title="${esc(title)}">${icon(iconName)}</button>`}

async function boot(){
  bindEvents();$('signInBtn').disabled=false;
  const diagnostic=CESApi.diagnostics();
  if(!diagnostic.ok){$('backendStatus').textContent='Connection setup required';showLoginConnectionError(diagnostic.message);return;}
  $('backendStatus').textContent='Checking Apps Script connection…';
  try{const health=await CESApi.call('health');if(!String(health?.version||'').startsWith('V34'))throw new Error('Backend version mismatch: expected V34, got '+(health?.version||'unknown')+'. Redeploy Apps Script V34.');$('backendStatus').textContent='Apps Script connected • '+health.version;}
  catch(e){const msg=errMsg(e);const isLegacy=/RPC method not allowed/i.test(msg);$('backendStatus').textContent=isLegacy?'Backend needs V34 deployment':'Backend connection needs checking';showLoginConnectionError(isLegacy?'The URL responds, but the Apps Script version is old. Deploy V34 Code.gs + Setup.gs as a new Web App version.':msg);}

  const tok=sessionStorage.getItem('ces_token');if(!tok)return;
  try{S.token=tok;showLoading(true);await loadBootstrap(true);showApp();await loadDashboard();startAutoSync()}
  catch(e){sessionStorage.removeItem('ces_token');S.token=null;console.warn(errMsg(e));$('appView')?.classList.add('hidden');$('loginView')?.classList.remove('hidden');showLoginConnectionError(/session/i.test(errMsg(e))?'Session expired. Please sign in again.':errMsg(e));}
  finally{showLoading(false)}
}
