function getFilterState(){return{compareYear:+$('compareYear').value,year:+$('year').value,site:$('site').value,vendor:$('vendor').value,hospital:$('hospital').value,group:$('group').value,modality:$('modality').value,equipmentType:$('equipmentType').value,model:$('model').value,status:$('status').value,maType:$('maType').value,quality:$('quality').value,scenario:$('scenario').value,sourceSheet:$('sourceSheet').value,priceAvailability:$('priceAvailability').value,dataReady:$('dataReady').value,risk:$('risk').value,ageBand:$('ageBand').value,contractWindow:$('contractWindow').value,movement:$('movement').value,priceMin:$('priceMin').value,priceMax:$('priceMax').value,changeMinPct:$('changeMinPct').value,changeMaxPct:$('changeMaxPct').value,sortBy:$('sortBy').value,search:$('search').value.trim(),page:S.equipmentPage,pageSize:S.equipmentPageSize};}
function restoreFilters(f){Object.entries(f||{}).forEach(([k,v])=>{const el=$(k);if(!el||v===null||v===undefined)return;if(el.tagName==='INPUT'||[...el.options].some(o=>o.value===String(v)))el.value=String(v)})}
function resetFilters(){['site','vendor','hospital','group','equipmentType','modality','model','status','maType','quality','scenario','sourceSheet','priceAvailability','dataReady','risk','ageBand','contractWindow','movement','priceMin','priceMax','changeMinPct','changeMaxPct','search'].forEach(id=>$(id).value='');$('compareYear').value=String(S.bootstrap.defaults.compareYear);$('year').value=String(S.bootstrap.defaults.year);S.equipmentPage=1;loadDashboardSafe()}
function activeFilterCount(){const f=getFilterState();return Object.entries(f).filter(([k,v])=>!['year','compareYear','sortBy'].includes(k)&&String(v||'')!=='').length}
async function loadDashboardSafe(){try{await loadDashboard()}catch(e){handleApiError(e)}}
async function loadDashboard(){const first=!S.data;if(first)showLoading(true);try{S.data=await CESApi.call('dashboard',S.token,getFilterState());S.rows=S.data.rows||[];S.equipmentPage=S.data.page||1;S.dataVersion=String(S.data.dataVersion);renderDashboard();renderEquipment();$('activeFilterCount').textContent=activeFilterCount()+' active';updateAlertCount()}finally{if(first)showLoading(false)}}
function updateAlertCount(){const upcoming=S.bootstrap?.renewalStats?.due90||0;const other=(S.data?.priorityActions||[]).filter(x=>!(x.reasons||[]).some(q=>q.type==='Contract expiring')).length;const n=upcoming+other;$('notificationCount').textContent=n>99?'99+':n;$('notificationCount').title=`${upcoming} equipment due to renew in 90 days • ${other} other priority alerts`;$('notificationCount').classList.toggle('hidden',!n)}
function renderDashboard(){const d=S.data,k=d.kpi||{};$('kEquip').textContent=(k.equipment||0).toLocaleString();$('kScope').textContent=`${k.sites||0} sites • ${k.vendors||0} vendors`;$('kCurLabel').textContent=`Contract value ${d.year}`;$('kCur').textContent=money(k.currentTotal);$('kYoyLabel').textContent=`Selected period ${d.compareYear} → ${d.year}`;$('kYoy').textContent=pct(k.yoy);$('kYoy').className=deltaClass(k.yoy);$('kYoySub').textContent=`${k.comparableRecords||0} paired records • ${(d.compareYear===d.year-1)?'YoY':'custom baseline'}`;$('kCoverage').textContent=pct(k.priceCoveragePct);$('kCoverageSub').textContent=`${k.pricedRecords||0}/${k.totalRecords||0} priced`;$('kRiskValue').textContent=money(k.contractAtRisk);$('kIssues').textContent=(k.dataIssues||0).toLocaleString();$('aDefective').textContent=k.defective||0;$('aOld').textContent=k.old8||0;$('aWarranty').textContent=k.warrantyExpiring||0;$('aExpiry').textContent=k.expiring90||0;$('aMissing').textContent=k.missingCurrent||0;renderCharts();renderVendorMovement();renderPriority();renderRecommendations();}
function chartDataEmpty(id,message){
  const canvas=$(id);if(!canvas)return;
  const wrap=canvas.closest('.chart-wrap');if(!wrap)return;
  let empty=wrap.querySelector('.chart-empty');if(!empty){empty=document.createElement('div');empty.className='chart-empty';wrap.appendChild(empty);}
  const valid=!!message;canvas.style.display=valid?'none':'';empty.style.display=valid?'flex':'none';empty.textContent=message||'';
}
function fmtCompactBaht(v){
  const n=Number(v);if(!Number.isFinite(n))return '—';
  const a=Math.abs(n);return '฿'+(a>=1e9?(n/1e9).toLocaleString('en-US',{maximumFractionDigits:2})+'B':a>=1e6?(n/1e6).toLocaleString('en-US',{maximumFractionDigits:1})+'M':a>=1e3?(n/1e3).toLocaleString('en-US',{maximumFractionDigits:0})+'K':n.toLocaleString('en-US',{maximumFractionDigits:0}));
}
const CHART_STATUS_COLORS={'Active':'#13A27B','Decom':'#7A8699','Non-renew':'#8559B9','Renewal':'#3276D2','Added':'#17A6B6','In Warranty':'#E9AA3E','Defect':'#DD5966','Replace':'#D4793A','Unclassified':'#CBD5E1'};
const STATUS_ORDER=['Active','Decom','Non-renew','Renewal','Added','In Warranty','Defect','Replace','Unclassified'];
function chartOptions(legend=true,type='money',direction='vertical'){
  const moneyChart=type==='money', horizontal=direction==='horizontal';
  const axis={grid:{color:'#e9edf4',drawTicks:false},border:{display:false},ticks:{font:{family:'Prompt',size:10},color:'#64748b',padding:9,maxRotation:0,autoSkip:true}};
  return{
    responsive:true,maintainAspectRatio:false,indexAxis:horizontal?'y':'x',interaction:{mode:'nearest',intersect:false},animation:{duration:350},
    plugins:{legend:{display:legend,position:'bottom',align:'start',labels:{usePointStyle:true,pointStyle:'circle',boxWidth:8,boxHeight:8,padding:13,color:'#475569',font:{family:'Prompt',size:10}}},tooltip:{displayColors:true,backgroundColor:'#132a48',padding:11,titleFont:{family:'Prompt',size:11,weight:'600'},bodyFont:{family:'Prompt',size:10},callbacks:{label:c=>`${c.dataset.label||''}: ${moneyChart?money(c.parsed[horizontal?'x':'y']):num(c.parsed[horizontal?'x':'y'])}`}}},
    scales:horizontal?{x:{...axis,beginAtZero:true,ticks:{...axis.ticks,callback:v=>moneyChart?fmtCompactBaht(v):new Intl.NumberFormat('en-US').format(v)}},y:{...axis,grid:{display:false},ticks:{...axis.ticks,autoSkip:false}}}:
      {x:{...axis,grid:{display:false}},y:{...axis,beginAtZero:moneyChart,ticks:{...axis.ticks,callback:v=>moneyChart?fmtCompactBaht(v):new Intl.NumberFormat('en-US').format(v)}}}
  };
}
function chartScopeSummary(){
  const f=getFilterState(),keys=[['site','Site'],['vendor','Vendor'],['hospital','Hospital'],['group','Group'],['equipmentType','Type'],['status','Status']];
  const selections=keys.filter(([key])=>f[key]).map(([key,label])=>`${label}: ${f[key]}`);
  $('chartScope').textContent=`Filtered: ${(S.data?.totalRows||0).toLocaleString()} equipment · ${selections.join(' · ')||'All permitted sites & vendors'} · ${S.data?.compareYear||'—'} vs ${S.data?.year||'—'}`;
}
function sortChartItems(items,key,changeKey){
  const sort=$('chartSort')?.value||'value-desc', arr=(items||[]).slice();
  if(sort==='alpha')return arr.sort((a,b)=>String(a.vendor||a.site||a.type||'').localeCompare(String(b.vendor||b.site||b.type||'')));
  if(sort==='change-desc' && changeKey)return arr.sort((a,b)=>(b[changeKey]??-Infinity)-(a[changeKey]??-Infinity));
  return arr.sort(sort==='value-asc'?(a,b)=>(Number(a[key])||0)-(Number(b[key])||0):(a,b)=>(Number(b[key])||0)-(Number(a[key])||0));
}
function renderCharts(){
  const d=S.data||{},year=d.year,compareYear=d.compareYear;chartScopeSummary();
  Object.values(S.charts).forEach(c=>{if(c&&typeof c.destroy==='function')c.destroy()});Object.keys(S.charts).forEach(k=>S.charts[k]=null);
  if(typeof Chart==='undefined'){
    ['trendChart','siteChart','yoyChart','statusChart','equipmentTypeChart'].forEach(id=>chartDataEmpty(id,'Chart library not available. Reload the page or check the network.'));return;
  }
  Chart.defaults.font.family='Prompt';Chart.defaults.color='#566983';
  // All chart datasets are generated by apiDashboard_ after applying the same equipment filters.
  const vendors=sortChartItems(d.vendorComparison||[],'currentValue','deltaPct');
  chartDataEmpty('trendChart',!vendors.length?'No vendor data matches the selected filters.':'');
  $('trendMeta').textContent=`${vendors.length} vendors · ${compareYear} vs ${year} · same ${vendors.reduce((n,v)=>n+(v.records||0),0).toLocaleString()} paired assets · THB (not individual equipment price)`;
  if(vendors.length){
    const opt=chartOptions(true,'money','horizontal');opt.scales.y.ticks.autoSkip=false;opt.plugins.tooltip.callbacks.label=c=>`${c.dataset.label}: ${money(c.parsed.x)}`;
    opt.plugins.tooltip.callbacks.afterBody=items=>{const v=vendors[items[0]?.dataIndex];return v?`Change: ${pct(v.deltaPct)} · ${num(v.records)} matched equipment`:''};
    S.charts.trend=new Chart($('trendChart'),{type:'bar',data:{labels:vendors.map(v=>v.vendor),datasets:[{label:`Compare ${compareYear}`,data:vendors.map(v=>v.compareValue),backgroundColor:'#9DC0E4',borderRadius:3,maxBarThickness:14},{label:`Current ${year}`,data:vendors.map(v=>v.currentValue),backgroundColor:'#1465B9',borderRadius:3,maxBarThickness:14}]},options:opt});
  }
  const sites=sortChartItems(d.siteValues||[],'value'),main=sites.slice(0,10),remaining=sites.slice(10),otherValue=remaining.reduce((a,x)=>a+(Number(x.value)||0),0),shown=main.concat(remaining.length?[{site:`Other ${remaining.length} sites`,value:otherValue}]:[]);
  $('siteMeta').textContent=`${sites.length} sites · ${year} · ${main.length} shown${remaining.length?' + combined other':''} · THB`;
  chartDataEmpty('siteChart',!shown.length?'No sites match the selected filters.':'');
  if(shown.length){
    const opt=chartOptions(false,'money','horizontal');opt.scales.y.ticks.autoSkip=false;opt.plugins.tooltip.callbacks.label=c=>`Annual value: ${money(c.parsed.x)}`;
    S.charts.site=new Chart($('siteChart'),{type:'bar',data:{labels:shown.map(x=>x.site),datasets:[{label:`Value ${year}`,data:shown.map(x=>x.value),backgroundColor:shown.map((_,i)=>i===shown.length-1&&remaining.length?'#AEC0D1':'#3990CA'),borderRadius:4,maxBarThickness:20}]},options:opt});
  }
  const vs=sortChartItems(d.vendorStatusCounts||[],'total'),statusNames=STATUS_ORDER.filter(s=>vs.some(x=>(x.statuses||{})[s]));
  $('statusMeta').textContent=`${vs.length} vendors · ${vs.reduce((n,x)=>n+(x.total||0),0).toLocaleString()} assets · ${statusNames.length} status categories · click legend to hide/show`;
  chartDataEmpty('statusChart',!vs.length?'No equipment statuses for selected filters.':'');
  if(vs.length){
    const opt=chartOptions(true,'count','horizontal');opt.scales.x.stacked=true;opt.scales.y.stacked=true;opt.scales.y.ticks.autoSkip=false;
    opt.plugins.tooltip.callbacks.label=c=>`${c.dataset.label}: ${num(c.parsed.x)} equipment`;
    opt.plugins.tooltip.callbacks.footer=items=>`Vendor total: ${num(vs[items[0]?.dataIndex]?.total||0)}`;
    S.charts.status=new Chart($('statusChart'),{type:'bar',data:{labels:vs.map(x=>x.vendor),datasets:statusNames.map(s=>({label:s,data:vs.map(x=>Number((x.statuses||{})[s]||0)),backgroundColor:CHART_STATUS_COLORS[s],borderRadius:2,maxBarThickness:25}))},options:opt});
  }
  const types=sortChartItems(d.equipmentTypeValues||[],'count'),top=types.slice(0,11),rest=types.slice(11),shownTypes=top.concat(rest.length?[{type:`Other ${rest.length} types`,count:rest.reduce((a,x)=>a+(Number(x.count)||0),0)}]:[]);
  $('typeMeta').textContent=`${types.length} equipment types · ${types.reduce((a,x)=>a+(x.count||0),0).toLocaleString()} assets · filtered counts`;
  chartDataEmpty('equipmentTypeChart',!shownTypes.length?'No equipment types available for these filters.':'');
  if(shownTypes.length){const opt=chartOptions(false,'count','horizontal');opt.scales.y.ticks.autoSkip=false;opt.plugins.tooltip.callbacks.label=c=>`${num(c.parsed.x)} equipment`;S.charts.types=new Chart($('equipmentTypeChart'),{type:'bar',data:{labels:shownTypes.map(x=>x.type),datasets:[{label:'Equipment',data:shownTypes.map(x=>x.count),backgroundColor:'#3990CA',borderRadius:3,maxBarThickness:19}]},options:opt});}
  // Detailed annual changes live in an optional drilldown; KPI above stays visible.
  const yearly=d.yearlyYoy||[];
  $('yoyMeta').textContent=`(Current − previous) / previous · matched records only · compare-year zeros excluded`;
  $('yoyBreakdown').innerHTML=yearly.map(x=>`<div class="annual-stat ${x.year===d.year?'selected-year':''}"><b>${x.previousYear} → ${x.year}</b><span class="delta ${deltaClass(x.changePct)}">${pct(x.changePct)}</span><small>${num(x.records)} matched assets</small><small>${fmtCompactBaht(x.previousValue)} → ${fmtCompactBaht(x.currentValue)}</small></div>`).join('')||'<p class="chart-note">No annual paired values.</p>';
  const canPlot=yearly.some(x=>x.changePct!=null);chartDataEmpty('yoyChart',!canPlot?'No comparable annual prices.':'');
  if(canPlot){const opt=chartOptions(false,'count');opt.plugins.legend.display=false;opt.scales.y.ticks.callback=v=>v+'%';opt.plugins.tooltip.callbacks.label=c=>`Change: ${Number(c.raw).toFixed(2)}%`;
    opt.plugins.tooltip.callbacks.afterLabel=c=>{const x=yearly[c.dataIndex];return [`Matched equipment: ${num(x.records)}`,`Compare: ${money(x.previousValue)}`,`Current: ${money(x.currentValue)}`]};
    S.charts.yoy=new Chart($('yoyChart'),{type:'bar',data:{labels:yearly.map(x=>`${x.previousYear} → ${x.year}`),datasets:[{label:'Annual change %',data:yearly.map(x=>x.changePct==null?null:x.changePct*100),backgroundColor:yearly.map(x=>x.changePct==null?'#CBD5E1':x.changePct>=0?'#D86971':'#169B80'),borderRadius:5,maxBarThickness:34}]},options:opt});
  }
}

function renderVendorMovement(){
 const rows=sortChartItems(S.data?.vendorComparison||[],'currentValue','deltaPct');
 $('vendorMovement').innerHTML=`<div class="vendor-comparison-header"><span>Vendor</span><span>${S.data?.compareYear||'Base'}</span><span>${S.data?.year||'Now'}</span><span>Change</span></div>`+rows.map(x=>`<div class="vendor-comparison-row"><button type="button" data-vendor="${esc(x.vendor)}" title="Open vendor detail">${esc(x.vendor)}</button><span>${fmtCompactBaht(x.compareValue)}</span><strong>${fmtCompactBaht(x.currentValue)}</strong><span class="delta ${deltaClass(x.deltaPct)}">${pct(x.deltaPct)}</span></div>`).join('')+(rows.length?'':'<p class="muted">No matched vendor prices for these filters.</p>');
}
function renderPriority(){const rows=S.data.priorityActions||[];$('priorityBody').innerHTML=rows.map(x=>`<tr><td><b>${esc(x.site)}</b></td><td>${esc(x.vendor)}</td><td>${esc(x.equipment)}<br><small class="muted">${esc(x.model)}</small></td><td>${esc(x.nhCode)}</td><td>${money(x.currentPrice)}</td><td class="delta ${deltaClass(x.deltaPct)}">${pct(x.deltaPct)}</td><td>${(x.reasons||[]).map(r=>`<span class="status ${r.severity==='high'?'st-defective':r.severity==='medium'?'st-warranty':'st-other'}">${esc(r.type)}</span>`).join(' ')}</td><td>${actionButton('detail',x.recordId,'Detail','info')}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">No priority alerts for current filters.</td></tr>'}
function renderRecommendations(){const k=S.data.kpi||{},r=[];if((k.priceCoveragePct||0)<.8)r.push({level:'high',title:'Improve yearly price coverage',text:`Current price coverage is ${pct(k.priceCoveragePct)}. Complete missing yearly prices before vendor inflation decisions.`});if((k.expiring90||0)>0)r.push({level:'high',title:'Start renewal action',text:`${k.expiring90} contract records are within the configured expiry window. Prioritize high-value contracts first.`});if((k.warrantyExpiring||0)>0)r.push({level:'medium',title:'Warranty transition review',text:`${k.warrantyExpiring} equipment records are approaching warranty end. Confirm MA coverage and first-year post-warranty price.`});if((k.old8||0)>0)r.push({level:'medium',title:'EOL/EOS replacement planning',text:`${k.old8} equipment records are aged ≥ 8 years. Cross-check EOS/EOL and replacement budget.`});if((k.dataIssues||0)>0)r.push({level:'medium',title:'Close data-quality gaps',text:`${k.dataIssues} records require review. Fix Site, price basis, MA type and contract dates in source sheets.`});if(!r.length)r.push({level:'',title:'Data is in good shape',text:'No major action detected for the current scope and filters.'});$('recommendations').innerHTML=r.slice(0,6).map(x=>`<div class="recommendation ${x.level}"><b>${esc(x.title)}</b><p>${esc(x.text)}</p></div>`).join('')}
function renderEquipment(){
 const d=S.data||{},rows=S.rows||{},year=Number(d.year)||2027,prior=year-1;
 $('equipmentChangeHead').textContent=`YoY ${prior}→${year}`;
 $('rowCount').textContent=`${(d.totalRows||0).toLocaleString()} records`;
 $('equipmentBody').innerHTML=(S.rows||[]).map(r=>{
   const wd=daysUntil(r.warrantyDate),ed=daysUntil(r.endDate);
   const warranty=wd===null?'—':wd<0?'Expired':wd<=90?`<span class="status st-warranty">${wd}d</span>`:fmtDate(r.warrantyDate);
   const end=ed===null?'—':ed<0?`<span class="status st-decommission">Expired</span>`:ed<=90?`<span class="status st-defective">${ed}d</span>`:fmtDate(r.endDate);
   const yc=r.yoyPct;
   return `<tr><td class="select-col"><input class="eq-select" type="checkbox" value="${esc(r.recordId)}" ${S.selectedEquipment.has(r.recordId)?'checked':''}></td><td><b>${esc(r.site)}</b></td><td>${esc(r.hospital)}</td><td>${esc(r.vendor)}</td><td>${esc(r.equipment)}</td><td><span class="category-pill">${esc(r.equipmentType||'Unclassified')}</span></td><td>${esc(r.model)}</td><td>${esc(r.systemSn||'—')}</td><td><b>${esc(r.nhCode||'—')}</b></td><td>${statusBadge(r.status)}</td><td>${esc(r.oldMaType||'—')}</td><td>${fmtDate(r.oldEndDate)}</td><td>${esc(r.newMaType||r.maType||'—')}</td><td>${warranty}</td><td>${r.lifetimeYears===null?'—':(Number(r.lifetimeYears)>=8?`<span class="status st-warranty">${num(r.lifetimeYears)}y • EOL/EOS</span>`:num(r.lifetimeYears)+'y')}</td><td>${fmtDate(r.startDate)}</td><td>${end}</td>${[2024,2025,2026,2027,2028,2029].map(y=>`<td class="currency-cell" title="${esc(r.priceNotes?.[y]||'')}">${r['price'+y]===null&&r.priceNotes?.[y]?`<span class="price-note">${esc(r.priceNotes[y])}</span>`:money(r['price'+y])}</td>`).join('')}<td class="delta ${deltaClass(yc)}" title="${prior} → ${year}; only when both years have prices">${pct(yc)}</td><td>${esc(r.quality||'—')}</td><td><div class="action-row">${actionButton('detail',r.recordId,'Detail','info')}${actionButton('compare',r.recordId,'Compare same type by vendor','compare')}${r.canEdit?actionButton('edit',r.recordId,'Edit','edit'):''}</div></td></tr>`;
 }).join('')||'<tr><td colspan="26" class="muted">No equipment found.</td></tr>';
 $('equipPageLabel').textContent=`Page ${d.page||1} / ${d.pageCount||1}`;$('equipPrev').disabled=(d.page||1)<=1;$('equipNext').disabled=(d.page||1)>=(d.pageCount||1);$('selectEquipmentPage').checked=(S.rows||[]).length>0&&(S.rows||[]).every(r=>S.selectedEquipment.has(r.recordId));applyEquipmentColumnVisibility();updateBulkButton();
}

function equipmentAction(e){const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='detail')openDetail(id);else if(a==='edit')openEdit(id);else if(a==='compare')openCompareEquipment(id)}

function previousYearDeltaClient(r,year){const a=r['price'+(year-1)],b=r['price'+year];return a===null||a===undefined||a===0||b===null||b===undefined?null:(b-a)/a;}
function detailHtmlFromRow(r){
  const scenarios=(S.bootstrap?.years||[2024,2025,2026,2027,2028,2029]).map(y=>({year:y,scenario:r.preferredScenario||'Annual Contract',coverage:r.maType||'—',priceType:'Annual',price:r['price'+y],qualityBasis:r.quality||'Source: 2024-2029',sourceSheet:r.sourceSheet||'01_Equipment_Master'}));
  return `<div class="mini-kpis"><div class="mini-kpi"><span>Site</span><b>${esc(r.site||'—')}</b></div><div class="mini-kpi"><span>Vendor</span><b>${esc(r.vendor||'—')}</b></div><div class="mini-kpi"><span>NH Code</span><b>${esc(r.nhCode||'—')}</b></div><div class="mini-kpi"><span>Status</span><b>${esc(r.status||'—')}</b></div></div><div class="profile-form-grid detail-grid"><div><b>Hospital</b><p>${esc(r.hospital||'—')}</p></div><div><b>Group</b><p>${esc(r.group||'—')}</p></div><div><b>Equipment Type</b><p>${esc(r.equipmentType||'—')}</p></div><div><b>Equipment / Modality</b><p>${esc(r.equipment||'—')}</p></div><div><b>Model</b><p>${esc(r.model||'—')}</p></div><div><b>Serial No.</b><p>${esc(r.systemSn||'—')}</p></div><div><b>MA Type</b><p>${esc(r.maType||'—')}</p></div><div><b>Warranty</b><p>${fmtDate(r.warrantyDate)}</p></div><div><b>Age</b><p>${r.lifetimeYears===null?'—':num(r.lifetimeYears)+' years'}</p></div><div><b>Contract Start</b><p>${fmtDate(r.startDate)}</p></div><div><b>Contract End</b><p>${fmtDate(r.endDate)}</p></div><div><b>PM / Year</b><p>${num(r.pmYear)}</p></div><div><b>Remark</b><p>${esc(r.remark||'—')}</p></div></div><div class="v34-contract-grid"><section><h4>Old Contract · 2024–2026</h4><div><b>MA Type</b><span>${esc(r.oldMaType||'—')}</span></div><div><b>Start / End</b><span>${fmtDate(r.oldStartDate)} → ${fmtDate(r.oldEndDate)}</span></div><div><b>PM / Year</b><span>${r.oldPmYear??'—'}</span></div></section><section><h4>New Contract · 2027–2029</h4><div><b>MA Type</b><span>${esc(r.newMaType||r.maType||'—')}</span></div><div><b>Start / End</b><span>${fmtDate(r.newStartDate||r.startDate)} → ${fmtDate(r.newEndDate||r.endDate)}</span></div><div><b>PM / Year</b><span>${r.newPmYear??r.pmYear??'—'}</span></div></section></div>${r.componentDetails?`<div class="v34-component"><b>Linked equipment (no separate price): </b>${esc(r.componentDetails)}</div>`:''}<div class="detail-actions"><button class="secondary compact" type="button" onclick="openAuditHistory('${esc(r.recordId)}','${esc(r.site)}')">Audit History</button></div><h4>Yearly contract price</h4><div class="table-scroll"><table><thead><tr><th>Year</th><th>Scenario</th><th>Coverage</th><th>Price</th><th>YoY change</th><th>Quality</th><th>Source</th></tr></thead><tbody>${scenarios.map(x=>`<tr><td>${x.year}</td><td>${esc(x.scenario)}</td><td>${esc(x.coverage)}</td><td>${x.price===null&&r.priceNotes?.[x.year]?`<span class="price-note">${esc(r.priceNotes[x.year])}</span>`:money(x.price)}</td><td class="delta ${deltaClass(previousYearDeltaClient(r,x.year))}">${pct(previousYearDeltaClient(r,x.year))}</td><td>${esc(x.qualityBasis)}</td><td>${esc(x.sourceSheet)}</td></tr>`).join('')}</tbody></table></div>`;
}
async function openDetail(id){
  const local=findRow(id);
  $('detailBody').innerHTML=local?detailHtmlFromRow(local):'<div class="inline-loading">Loading equipment detail…</div>';
  $('detailModal').classList.remove('hidden');
  if(local)return;
  try{const d=await CESApi.call('contractDetail',S.token,id),m=d.master;const r={site:m.Site,vendor:m.Vendor,nhCode:m.NH_Code,status:m.Status_Canonical,hospital:m.Hospital,group:m.Group,equipment:m.Modality,equipmentType:m.Equipment_Type,model:m.Model,systemSn:m.System_SN,maType:m.MA_Category,warrantyDate:m.Warranty_Date,endDate:m.End_Date,startDate:m.Start_Date,recordId:m.Record_ID,lifetimeYears:m.Lifetime_Years,pmYear:m.PM_Year,remark:m.Remark,preferredScenario:m.Preferred_Scenario||'Annual Contract',quality:m.Price_Data_Quality||'Source: 2024-2029',sourceSheet:m.Source_Sheet||'01_Equipment_Master',oldMaType:m.Old_MA_Type,oldStartDate:m.Old_Start_Date,oldEndDate:m.Old_End_Date,oldPmYear:m.Old_PM_Year,newMaType:m.New_MA_Type,newStartDate:m.New_Start_Date,newEndDate:m.New_End_Date,newPmYear:m.New_PM_Year,componentDetails:m.Component_Details,sourcePriceNotes:m.Source_Price_Notes,priceNotes:Object.fromEntries((d.scenarios||[]).map(v=>[v.year,v.priceNote||'']))};(d.scenarios||[]).forEach(x=>r['price'+x.year]=x.price);$('detailBody').innerHTML=detailHtmlFromRow(r)}catch(e){$('detailBody').innerHTML=`<div class="error-box">${esc(errMsg(e))}</div>`}}

function findRow(id){return S.rows.find(r=>r.recordId===id)}
