function openProfile(){$('profileMenu').classList.add('hidden');const p=S.profile,canEdit=p&&p.role==='ADMIN';$('pUserId').value=p.staffId||'';$('pRole').value=p.role||'';$('pEngName').value=p.engName||'';$('pThName').value=p.thName||'';$('pEmail').value=p.email||'';$('pPosition').value=p.position||'';$('pTelephone').value=p.telephone||'';$('pSite').value=p.profileSite||p.allowedSites?.[0]||'';$('pGroup').value=p.profileGroup||p.allowedGroups?.[0]||'';$('pViewScope').textContent=p.canViewAllSites?'All Sites':(p.allowedSites||[]).join(', ')||'Group scope';$('pEditPermission').textContent=p.canEditData?'Allowed':'Read only';['pEngName','pThName','pEmail','pPosition','pTelephone','pSite','pGroup'].forEach(id=>$(id).disabled=!canEdit);$('profileSaveBtn').classList.toggle('hidden',!canEdit);$('profileEditHint').textContent=canEdit?'ADMIN can edit profile data and save directly to 06_Staff_Access.':'Profile is read-only. Only ADMIN can edit profile data.';$('profileModal').classList.remove('hidden')}
