const EQUIP_COLS=[['site','Site',2],['hospital','Hospital',3],['vendor','Vendor',4],['equipment','Modality',5],['equipmentType','Equipment Type',6],['model','Model',7],['sn','S/N',8],['nh','NH Code',9],['status','Status',10],['oldMa','Old MA',11],['oldEnd','Old End',12],['contractType','New MA',13],['warranty','Warranty',14],['age','Age',15],['start','New Start',16],['end','New End',17],['2024','2024',18],['2025','2025',19],['2026','2026',20],['2027','2027',21],['2028','2028',22],['2029','2029',23],['change','YoY Change',24],['quality','Quality',25]];
function visibleEquipmentColumns(){try{const x=JSON.parse(localStorage.getItem('ces_equipment_columns_v34')||'null');return Array.isArray(x)&&x.length?new Set(x):new Set(EQUIP_COLS.map(x=>x[0]))}catch(_){return new Set(EQUIP_COLS.map(x=>x[0]))}}
function applyEquipmentColumnVisibility(){const t=$('equipmentTable');if(!t)return;const v=visibleEquipmentColumns();EQUIP_COLS.forEach(([key,label,index])=>{t.querySelectorAll(`tr>*:nth-child(${index})`).forEach(el=>el.classList.toggle('col-hidden',!v.has(key)))})}
function openColumnChooser(){const v=visibleEquipmentColumns();$('columnChoices').innerHTML=EQUIP_COLS.map(([k,l])=>`<label class="site-choice"><input type="checkbox" value="${k}" ${v.has(k)?'checked':''}><span>${l}</span></label>`).join('');$('columnsModal').classList.remove('hidden')}
function saveColumnChooser(){const vals=[...$('columnChoices').querySelectorAll('input:checked')].map(x=>x.value);localStorage.setItem('ces_equipment_columns_v34',JSON.stringify(vals));applyEquipmentColumnVisibility();$('columnsModal').classList.add('hidden');toast('Equipment columns updated')}
function resetColumnChooser(){localStorage.removeItem('ces_equipment_columns_v34');openColumnChooser();applyEquipmentColumnVisibility()}
function equipmentSelectionChanged(e){const c=e.target.closest('.eq-select');if(!c)return;c.checked?S.selectedEquipment.add(c.value):S.selectedEquipment.delete(c.value);updateBulkButton();$('selectEquipmentPage').checked=S.rows.length>0&&S.rows.every(r=>S.selectedEquipment.has(r.recordId))}
function toggleSelectEquipmentPage(){const on=$('selectEquipmentPage').checked;(S.rows||[]).forEach(r=>on?S.selectedEquipment.add(r.recordId):S.selectedEquipment.delete(r.recordId));renderEquipment()}
function updateBulkButton(){if(!$('bulkEditBtn'))return;const n=S.selectedEquipment.size;$('bulkEditBtn').innerHTML=icon('edit')+(n?`Bulk Edit (${n})`:'Bulk Edit')}
function openBulkEdit(){if(!S.profile.canEditData)return toast('Edit permission required');const ids=[...S.selectedEquipment];if(!ids.length)return toast('Select equipment rows first');$('bulkEditCount').textContent=ids.length;$('bulkStatus').value='';$('bulkMa').value='';$('bulkStart').value='';$('bulkEnd').value='';$('bulkPm').value='';$('bulkRemark').value='';$('bulkNote').value='';$('bulkEditModal').classList.remove('hidden')}
async function saveBulkEdit(e){e.preventDefault();const ids=[...S.selectedEquipment];if(!ids.length)return;showLoading(true);try{const r=await CESApi.call('bulkSaveOverrides',S.token,{recordIds:ids,status:$('bulkStatus').value,maCategory:$('bulkMa').value,startDate:$('bulkStart').value,endDate:$('bulkEnd').value,pmYear:$('bulkPm').value,appendRemark:$('bulkRemark').value,note:$('bulkNote').value});S.selectedEquipment.clear();$('bulkEditModal').classList.add('hidden');await loadDashboard();toast(`${r.updated||0} equipment record(s) updated`)}catch(e){handleApiError(e)}finally{showLoading(false)}}
function savedViews(){try{return JSON.parse(localStorage.getItem('ces_saved_views')||'[]')}catch(_){return[]}}
function openSavedViews(){renderSavedViews();$('savedViewsModal').classList.remove('hidden')}
function currentViewState(){return S.page==='contracts'?{page:'contracts',filters:currentContractFilter(false)}:{page:S.page==='equipment'?'equipment':'dashboard',filters:getFilterState()}}
function saveCurrentView(){const name=$('savedViewName').value.trim();if(!name)return toast('Enter a view name');const all=savedViews(),state=currentViewState();all.push({id:'V'+Date.now(),name,page:state.page,filters:state.filters,createdAt:new Date().toISOString()});localStorage.setItem('ces_saved_views',JSON.stringify(all.slice(-30)));$('savedViewName').value='';renderSavedViews();toast('View saved')}
function renderSavedViews(){const all=savedViews();$('savedViewsList').innerHTML=all.map(v=>`<div class="saved-view-row"><div><b>${esc(v.name)}</b><small>${esc(v.page)} • ${fmtDateTime(v.createdAt)}</small></div><div class="action-row"><button class="secondary compact" data-view-action="load" data-id="${v.id}">Load</button><button class="ghost compact" data-view-action="delete" data-id="${v.id}">Delete</button></div></div>`).join('')||'<div class="muted">No saved views on this browser.</div>'}
function savedViewAction(e){const b=e.target.closest('[data-view-action]');if(!b)return;let all=savedViews(),v=all.find(x=>x.id===b.dataset.id);if(b.dataset.viewAction==='delete'){all=all.filter(x=>x.id!==b.dataset.id);localStorage.setItem('ces_saved_views',JSON.stringify(all));return renderSavedViews()}if(!v)return;$('savedViewsModal').classList.add('hidden');switchPage(v.page);setTimeout(()=>{if(v.page==='contracts'){Object.entries(v.filters||{}).forEach(([k,val])=>{const map={site:'contractSite',vendor:'contractVendor',hospital:'contractHospital',group:'contractGroup',maType:'contractMaType',equipment:'contractEquipment',status:'contractStatus',expiry:'contractExpiry',year:'contractYear',search:'contractSearch'};if(map[k]&&$(map[k]))$(map[k]).value=val||''});S.contractPage=1;loadSiteContracts()}else{restoreFilters(v.filters||{});S.equipmentPage=1;loadDashboardSafe()}},0)}
async function openAuditHistory(recordId,site){$('auditIdentity').textContent=recordId;$('auditHistoryBody').innerHTML='<div class="inline-loading">Loading history…</div>';$('auditModal').classList.remove('hidden');try{const rows=await CESApi.call('auditHistory',S.token,recordId,site);$('auditHistoryBody').innerHTML=rows.map(x=>`<div class="audit-item"><div class="audit-dot"></div><div><b>${esc(x.action)}</b><small>${fmtDateTime(x.timestamp)} • ${esc(x.staffId||'SYSTEM')}</small><pre>${esc(JSON.stringify(x.detail||{},null,2))}</pre></div></div>`).join('')||'<div class="muted">No audit history for this record.</div>'}catch(e){$('auditHistoryBody').innerHTML=`<div class="error-box">${esc(errMsg(e))}</div>`}}
async function openRenewalCenter(){S.renewalPage=1;$('renewalModal').classList.remove('hidden');await loadRenewalQueue()}
async function loadRenewalQueue(){showLoading(true);try{const f=S.page==='contracts'?currentContractFilter(false):getFilterState();const d=await CESApi.call('renewalQueue',S.token,Object.assign({},f,{days:+$('renewalDays').value||90}));S.renewals=d.rows||[];S.renewalMeta=d;renderRenewalQueue()}catch(e){handleApiError(e)}finally{showLoading(false)}}
function filteredRenewals(){const q=$('renewalSearch').value.trim().toLowerCase(),st=$('renewalStatusFilter').value;return(S.renewals||[]).filter(x=>(!st||x.renewalStatus===st)&&(!q||[x.site,x.hospital,x.vendor,x.maType,x.renewalOwner].join(' ').toLowerCase().includes(q)))}
function renderRenewalQueue(){const rows=filteredRenewals(),m=S.renewalMeta||{},y=m.year||S.data?.year||2027;$('renewalSummary').innerHTML=`<div class="mini-kpi"><span>Contracts</span><b>${rows.length}</b></div><div class="mini-kpi"><span>Equipment</span><b>${rows.reduce((a,c)=>a+c.equipmentCount,0)}</b></div><div class="mini-kpi"><span>${y} value</span><b>${money(rows.reduce((a,c)=>a+(Number(c.priceYears?.[y])||0),0))}</b></div><div class="mini-kpi"><span>Due ≤30 days</span><b>${rows.filter(x=>x.daysLeft<=30).length}</b></div>`;$('renewalBody').innerHTML=rows.slice(0,100).map(x=>`<tr><td><b>${esc(x.site)}</b></td><td>${esc(x.vendor)}</td><td>${esc(x.maType)}</td><td>${fmtDate(x.endDate)}</td><td>${x.daysLeft}d</td><td>${x.equipmentCount}</td><td>${money(x.priceYears?.[y]||0)}</td><td>${esc(x.renewalStatus||'To Review')}</td><td>${esc(x.renewalOwner||'—')}</td><td><button class="action-btn" data-renewal-action="edit" data-key="${esc(x.contractKey)}">${icon('edit')}</button></td></tr>`).join('')||'<tr><td colspan="10" class="muted">No contracts due for renewal in the selected window.</td></tr>'}
function renewalRowAction(e){const b=e.target.closest('[data-renewal-action]');if(!b)return;const x=(S.renewals||[]).find(r=>r.contractKey===b.dataset.key);if(!x)return;$('renewalActionKey').value=x.contractKey;$('renewalActionSite').value=x.site;$('renewalActionIdentity').textContent=`${x.site} • ${x.vendor} • ${x.maType} • ${fmtDate(x.endDate)}`;$('renewalActionStatus').value=x.renewalStatus||'To Review';$('renewalActionOwner').value=x.renewalOwner||'';$('renewalActionDue').value=(x.renewalDueDate||'').slice(0,10);$('renewalActionNote').value=x.renewalNote||'';$('renewalActionModal').classList.remove('hidden')}
async function saveRenewalAction(e){e.preventDefault();showLoading(true);try{await CESApi.call('saveRenewalAction',S.token,{contractKey:$('renewalActionKey').value,site:$('renewalActionSite').value,status:$('renewalActionStatus').value,owner:$('renewalActionOwner').value,dueDate:$('renewalActionDue').value,note:$('renewalActionNote').value});$('renewalActionModal').classList.add('hidden');await loadRenewalQueue();toast('Renewal action saved to Audit Log')}catch(e){handleApiError(e)}finally{showLoading(false)}}
async function sendRenewalEmailNow(){showLoading(true);try{const site=S.page==='contracts'?$('contractSite').value:'';const r=await CESApi.call('sendRenewalNotification',S.token,site||'');const sent=r.filter(x=>x.sent).length,count=r.reduce((a,x)=>a+(x.count||0),0);toast(`Renewal notification sent • ${sent} site(s) • ${count} contract(s)`)}catch(e){handleApiError(e)}finally{showLoading(false)}}

async function openAlertCenter(){
 $('alertModal').classList.remove('hidden');$('alertCenter').innerHTML='<div class="inline-loading">Checking upcoming renewal dates from End_Date…</div>';
 try{
 const d=await CESApi.call('renewalAlerts',S.token,90),p=S.data?.priorityActions||[];
 $('alertCenter').innerHTML=`<div class="mini-kpis"><div class="mini-kpi"><span>Renewal due ≤ 30 days</span><b class="renewal-risk">${d.due30}</b></div><div class="mini-kpi"><span>Due ≤ 60 days</span><b>${d.due60}</b></div><div class="mini-kpi"><span>Due ≤ 90 days</span><b>${d.due90}</b></div><div class="mini-kpi"><span>Priority alerts</span><b>${p.length}</b></div></div><div class="alert-section-title"><h4>Upcoming re-contract • 90 days</h4><button class="secondary compact" id="alertRenewalOpen" type="button">Open Renewal Center</button></div><p class="muted">Uses End_Date from 01_Equipment_Master across all permitted Sites, independent of dashboard filters. Showing first ${d.rows.length} of ${d.total} records, sorted by due date.</p><div class="table-scroll alert-due-list"><table><thead><tr><th>Days left</th><th>End Date</th><th>Site</th><th>Vendor</th><th>Equipment Type</th><th>Equipment</th><th>Contract Type</th><th>NH Code</th></tr></thead><tbody>${d.rows.map(x=>`<tr><td><span class="status ${x.daysLeft<=30?'st-defective':'st-warranty'}">${x.daysLeft}d</span></td><td>${fmtDate(x.endDate)}</td><td>${esc(x.site)}</td><td>${esc(x.vendor)}</td><td>${esc(x.equipmentType)}</td><td>${esc(x.equipment)}</td><td>${esc(x.maType)}</td><td>${esc(x.nhCode)}</td></tr>`).join('')||'<tr><td colspan="8">No upcoming renewals.</td></tr>'}</tbody></table></div><h4>Other priority alerts</h4><div class="table-scroll"><table><thead><tr><th>Site</th><th>Vendor</th><th>Equipment</th><th>NH Code</th><th>Reason</th></tr></thead><tbody>${p.map(x=>`<tr><td>${esc(x.site)}</td><td>${esc(x.vendor)}</td><td>${esc(x.equipment)} ${esc(x.model)}</td><td>${esc(x.nhCode)}</td><td>${(x.reasons||[]).map(r=>esc(r.type)).join(', ')}</td></tr>`).join('')||'<tr><td colspan="5">No other alerts.</td></tr>'}</tbody></table></div>`;
 $('alertRenewalOpen').onclick=()=>{$('alertModal').classList.add('hidden');openRenewalCenter();};
 }catch(e){$('alertCenter').innerHTML=`<div class="error-box">${esc(errMsg(e))}</div>`;}
}

function handleCommand(cmd){if(cmd==='sync')checkSync(true);else if(cmd==='notify')openAlertCenter();else if(cmd==='reset')resetFilters();else if(cmd==='excel')exportEquipment();else if(cmd==='pdf')window.print()}
function handleExport(type){if(type==='contracts-excel')exportContracts();else if(type==='contracts-pdf')window.print()}
function exportXlsx(name,rows){if(window.XLSX){const wb=XLSX.utils.book_new(),ws=XLSX.utils.aoa_to_sheet(rows);XLSX.utils.book_append_sheet(wb,ws,'Data');XLSX.writeFile(wb,`${name}_${new Date().toISOString().slice(0,10)}.xlsx`);return}const csv='\ufeff'+rows.map(a=>a.map(csvCell).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name+'.csv';a.click();URL.revokeObjectURL(a.href)}
async function exportEquipment(){showLoading(true);try{const d=await CESApi.call('dashboardExport',S.token,getFilterState()),h=['Site','Hospital','Group','Vendor','Equipment','Equipment Type','Model','S/N','NH Code','Status','Old MA','Old Start','Old End','New MA','New Start','New End','Warranty','Lifetime','PM/Year','2024','2025','2026','2027','2028','2029','2024 Note','2025 Note','2026 Note','2027 Note','2028 Note','2029 Note','YoY % (previous year)','Quality','Source','Remark'],rows=(d.rows||[]).map(r=>[r.site,r.hospital,r.group,r.vendor,r.equipment,r.equipmentType,r.model,r.systemSn,r.nhCode,r.status,r.oldMaType,r.oldStartDate,r.oldEndDate,r.newMaType,r.newStartDate,r.newEndDate,r.warrantyDate,r.lifetimeYears,r.pmYear,r.price2024,r.price2025,r.price2026,r.price2027,r.price2028,r.price2029,...[2024,2025,2026,2027,2028,2029].map(y=>r.priceNotes?.[y]||''),r.yoyPct===null?'':r.yoyPct*100,r.quality,r.sourceSheet,r.remark]);exportXlsx('CES_Equipment_Contract',[h,...rows])}catch(e){handleApiError(e)}finally{showLoading(false)}}
async function exportContracts(){showLoading(true);try{const y=+$('contractYear').value,d=await CESApi.call('siteContracts',S.token,currentContractFilter(true)),rows=d?.rows||[],h=['Site','Hospital','Group','Vendor','MA Type','Start','End','Equipment','Active','Defective','Decommission',`${y} Value`,'File Count'];exportXlsx('CES_Site_Contracts',[h,...rows.map(c=>[c.site,c.hospital,c.group,c.vendor,c.maType,c.startDate,c.endDate,c.equipmentCount,c.active,c.defective,c.decommission,c.priceYears?.[y]||'',c.files?.length||0])])}catch(e){handleApiError(e)}finally{showLoading(false)}}

function globalSearchChanged(){const q=$('globalSearch').value;if(S.page==='contracts'){$('contractSearch').value=q;S.contractPage=1;clearTimeout(globalSearchChanged.ct);globalSearchChanged.ct=setTimeout(loadSiteContracts,240)}else if(S.page==='users'){$('staffSearch').value=q;S.staffPage=1;renderUsers()}else{$('search').value=q;clearTimeout(globalSearchChanged.t);globalSearchChanged.t=setTimeout(()=>{S.equipmentPage=1;loadDashboardSafe()},280)}}
function switchPage(page){if(page==='users'&&!S.profile.canManageAccess)return;S.page=page;document.querySelectorAll('.page-view').forEach(p=>p.classList.remove('active'));$(`page-${page}`).classList.add('active');document.querySelectorAll('.nav-btn[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const m={dashboard:['PRICE INTELLIGENCE','Dashboard','Executive contract price, risk and data-quality overview.'],contracts:['CONTRACT MANAGEMENT','Site Contract Detail','Contract-level summary, files, renewals and Site actions.'],equipment:['ASSET DETAIL','Equipment','Equipment-level contract price, warranty, status and comparison.'],users:['ACCESS CONTROL','User Management','User profile, role and Site permission.'],settings:['SYSTEM','Setting','Live sync, alert, notification and data configuration.']};$('pageEyebrow').textContent=m[page][0];$('pageTitle').textContent=m[page][1];$('pageSubtitle').textContent=m[page][2];$('dataToolbar').classList.toggle('hidden',!['dashboard','equipment'].includes(page));if(page==='contracts')loadSiteContracts();if(page==='users')loadUsers();if(page==='settings')loadSettings();$('sidebar').classList.remove('mobile-open')}
async function refreshAll(){showLoading(true);try{await loadBootstrap(true);await loadDashboard();if(S.page==='contracts')await loadSiteContracts();if(S.page==='users')await loadUsers();if(S.page==='settings')await loadSettings();toast('Data synchronized')}catch(e){handleApiError(e)}finally{showLoading(false)}}
function getSyncSec(){const n=Number(localStorage.getItem('ces_sync_sec')||S.bootstrap?.defaults?.autoSyncSec||10);return[5,10,15,30,60,120].includes(n)?n:10}
function startAutoSync(){clearInterval(S.syncTimer);const sec=getSyncSec();setSyncState('Live sync',`Every ${sec} sec`,'green');S.syncTimer=setInterval(()=>{if(!document.hidden)checkSync(false)},sec*1000)}
async function checkSync(force){if(!S.token)return;setSyncState('Checking…','Google Sheet','orange');try{const r=await CESApi.call('syncStatus',S.token,S.dataVersion);S.profile=r.profile||S.profile;updateProfileUi();$('userNav').classList.toggle('hidden',!S.profile.canManageAccess);if(r.changed){S.dataVersion=String(r.dataVersion);await loadBootstrap(true);await loadDashboard();if(S.page==='contracts')await loadSiteContracts();if(S.page==='users')await loadUsers();if(S.page==='settings')await loadSettings();toast('Sheet changed • synchronized')}setSyncState('Live sync',`Every ${getSyncSec()} sec`,'green')}catch(e){const m=errMsg(e);setSyncState('Sync issue','Click sync','red');if(/session expired|invalid session|session not found|session expired|session invalid/i.test(m)){clearSessionOnExpiry('Session expired. Please sign in again.');return;}if(force)toast(m);console.warn('CES sync error',m)}}
function handleApiError(e){let msg=errMsg(e);if(/RPC method not allowed/i.test(msg))msg='Apps Script backend is older than the GitHub front end. Deploy the latest Apps Script code as a NEW VERSION, then refresh this page.';if(/session expired|invalid session|session not found|session invalid/i.test(msg)){clearSessionOnExpiry('Session expired. Please sign in again.');return}toast(msg)}
boot();
